log.raw:
{
  "understanding": {
    "purpose": "Show order line items with product variants, quantities, charges, warehouse locations, and shipment tracking.",
    "reading": "Readers scan each row from product identification through quantity and charges to fulfillment details, and compare quantities and amounts down their columns. Wrapping can make rows taller, so keeping related values aligned within each row matters.",
    "groups": [
      "ID and SKU identify the line and product.",
      "Color and Size describe the product variant.",
      "Qty, Price, Tax, and Total support comparison of quantities and charges.",
      "Warehouse and Tracking describe fulfillment and shipment."
    ],
    "keep_intact": [
      "Column headers should remain whole.",
      "Quantities, prices, tax, and totals should each stay on one line.",
      "Tracking identifiers should preferably stay intact; if split, they must remain inside their cells.",
      "SKU segments should remain intact where possible."
    ],
    "may_wrap": [
      "SKU values can wrap at hyphens, though excessive lines make comparison harder.",
      "Warehouse names can wrap at hyphens; their wrapping can share row height already created by SKU or tracking."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [37, 57, 61, 52, 47, 62, 53, 68, 102, 180],
      "idea": "Fit the viewport and keep tracking intact, accepting tall rows from a narrow SKU column."
    },
    {
      "name": "B",
      "widths": [37, 110, 61, 52, 47, 62, 53, 68, 102, 127],
      "idea": "Fit the viewport with more balanced SKU and tracking widths, accepting contained tracking splits and natural warehouse wrapping."
    },
    {
      "name": "C",
      "widths": [37, 157, 61, 52, 47, 62, 53, 68, 102, 180],
      "idea": "Keep SKU and tracking identifiers intact and let warehouse names wrap, using horizontal scrolling for the final part of tracking."
    }
  ]
}
